import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 9999 and floors", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(9999)).toBe(999);
  });

  it("computes 15% of 1000", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(1000)).toBe(150);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("floors the result (33.33% of 100 = 33 not 33.33)", () => {
    const p = new PercentageDiscountPolicy(33.33);
    expect(p.computeDiscountCents(100)).toBe(33);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(25);
    expect(p.computeDiscountCents(1_000_000_00)).toBe(25_000_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(1.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when amount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discount from multiple policies using original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% = 160% which is > subtotal
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum when mode not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(100),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("compounds discounts sequentially", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500 → remaining = 500
      // Second: 50% of 500 = 250 → total discount = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // c1: 200 off 1000 = remaining 800, then 50% of 800 = 400, total = 600
      // c2: 50% of 1000 = 500 remaining 500, then min(200,500) = 200, total = 700
      expect(composite1.computeDiscountCents(1000)).toBe(600);
      expect(composite2.computeDiscountCents(1000)).toBe(700);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 100% of 1000 = 1000 → remaining = 0; fixed tries on 0 → 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

