toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weightGrams: number, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(1.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 1.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart below threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 4999)).toBe(599);
  });

  it("returns 0 when subtotal meets threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 5001)).toBe(0);
  });

  it("returns 0 for empty cart regardless of threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([], 100)).toBe(0);
  });

  it("returns flat fee without threshold configured", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([line("a", 200)], 100000)).toBe(799);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a", 100)], 100)).toBe(0);
  });

  it("accepts 0 freeOverCents (always free when items present)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([line("a", 100)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("rejects bracket with upToGrams <= 0", () => {
    expect(() => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }])).toThrow(
      RangeError,
    );
  });

  it("rejects bracket with negative costCents", () => {
    expect(() => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }])).toThrow(
      RangeError,
    );
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], 1.5),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
    ];
    expect(calc.computeShippingCents(lines, 1000)).toBe(0);
  });

  it("selects first bracket at boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
  });

  it("selects second bracket above first boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(600);
  });

  it("selects second bracket at its boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 1000)], 1000)).toBe(600);
  });

  it("selects third bracket", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 2000)], 1000)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 2000);
    expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1200);
  });

  it("sorts brackets by upToGrams regardless of input order", () => {
    const unordered = [
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
  });

  it("accumulates weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 250g * 3 = 750g → second bracket
    expect(calc.computeShippingCents([line("a", 250, 3)], 1000)).toBe(600);
  });
});

