import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000, weightGrams: 100 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 200 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices from priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
    });
  });

  describe("inventory checking", () => {
    it("succeeds when all items available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item not available", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("first denial wins with multiple items", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("b");
      }
    });

    it("generates default message when reason not provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.available).toBeUndefined();
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(100);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });

    it("applies discount before async tax", async () => {
      const { PercentageDiscountPolicy } = await import("../src/pricing.ts");
      const cart = new Cart({ discountPolicy: new PercentageDiscountPolicy(50) });
      cart.add(productA, 1); // subtotal 1000, discount 500, taxable = 500

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(50); // 10% of 500
    });
  });

  describe("full pipeline composition", () => {
    it("price refresh + inventory + async tax + shipping", async () => {
      const { FlatShippingCalculator } = await import("../src/shipping.ts");
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a → 1200
          .mockResolvedValueOnce(2500), // b → 2500
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal: 1200*2 + 2500*1 = 4900
      expect(result.totals.subtotalCents).toBe(4900);
      expect(result.totals.discountCents).toBe(0);
      // tax: 5% of 4900 = 245
      expect(result.totals.taxCents).toBe(245);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(4900 + 245 + 500);
    });

    it("works without any collaborators", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns lines snapshot in result", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("a");
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });
});

describe("InventoryError", () => {
  it("has correct shape", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

